package com.rikkeibank.account.controller; import com.rikkeibank.account.dto.AccountTypeRequest; import com.rikkeibank.account.model.AccountType; import com.rikkeibank.account.service.AccountTypeService; import jakarta.validation.Valid; import java.util.*; import org.springframework.http.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/account-types") public class AccountTypeController{private final AccountTypeService s;public AccountTypeController(AccountTypeService s){this.s=s;}@GetMapping @PreAuthorize("hasAnyRole('ADMIN','CUSTOMER','TELLER')") public List<AccountType> all(){return s.all();}@GetMapping("/{id}") @PreAuthorize("isAuthenticated()") public AccountType one(@PathVariable Long id){return s.find(id);}@PostMapping @PreAuthorize("hasRole('ADMIN')") public ResponseEntity<AccountType> create(@Valid @RequestBody AccountTypeRequest r){return ResponseEntity.status(201).body(s.create(r));}@PutMapping("/{id}") @PreAuthorize("hasRole('ADMIN')") public AccountType update(@PathVariable Long id,@Valid @RequestBody AccountTypeRequest r){return s.update(id,r);}@DeleteMapping("/{id}") @PreAuthorize("hasRole('ADMIN')") public ResponseEntity<Void> delete(@PathVariable Long id){s.delete(id);return ResponseEntity.noContent().build();}}
